585	        <article id="get-started">
586	            <h2>Get Started</h2>
587	            <p>
588	                Use this template as a foundation for your next project. It's clean, well-structured, and ready to be
589	                customized to meet your specific needs.
590	            </p>
591	            <form id="contact-form" method="POST" data-endpoint="/contact">
592	                <fieldset>
593	                    <legend>Get in Touch</legend>
594	                    <p class="form-info"><span style="color: var(--error-color); font-weight: 600;">*</span> indicates required fields</p>
595	                    <div class="form-group">
596	                        <label for="name" class="required">Name</label>
597	                        <input type="text" id="name" name="name" placeholder="Your full name" required aria-required="true" aria-describedby="name-error" minlength="2" pattern="[A-Za-z\s]{2,}">
598	                        <div class="field-error" id="name-error"></div>
599	                    </div>
600	                    <div class="form-group">
601	                        <label for="email" class="required">Email</label>
602	                        <input type="email" id="email" name="email" placeholder="you@example.com" required aria-required="true" aria-describedby="email-error">
603	                        <div class="field-error" id="email-error"></div>
604	                    </div>
605	                    <div class="form-group">
606	                        <label for="message" class="required">Message <span>(10-1000 characters)</span></label>
607	                        <textarea id="message" name="message" placeholder="Tell us what you think..." required aria-required="true" aria-describedby="message-error message-counter" minlength="10" maxlength="1000"></textarea>
608	                        <div class="field-error" id="message-error"></div>
609	                        <div id="message-counter" style="font-size: 0.85rem; color: var(--text-color); margin-top: 0.25rem; opacity: 0.7;">0 / 1000</div>
610	                    </div>
