647	    <script>
648	        document.addEventListener('DOMContentLoaded', function() {
649	            document.getElementById('year').textContent = new Date().getFullYear();
650	
651	            const menuToggle = document.querySelector('.menu-toggle');
652	            const navMenu = document.getElementById('nav-menu');
653	
654	            if (menuToggle) {
655	                const closeMenu = () => {
656	                    menuToggle.setAttribute('aria-expanded', 'false');
657	                    navMenu.setAttribute('hidden', '');
658	                    menuToggle.focus();
659	                };
660	
661	                menuToggle.addEventListener('click', function() {
662	                    const isExpanded = menuToggle.getAttribute('aria-expanded') === 'true';
663	                    menuToggle.setAttribute('aria-expanded', !isExpanded);
664	                    navMenu.toggleAttribute('hidden');
665	                });
666	
667	                document.addEventListener('keydown', (e) => {
668	                    if (e.key === 'Escape' && menuToggle.getAttribute('aria-expanded') === 'true') {
669	                        closeMenu();
670	                    }
671	                });
672	
673	                const navLinks = navMenu.querySelectorAll('a');
674	                navLinks.forEach(link => {
675	                    link.addEventListener('click', closeMenu);
676	                });
677	            }
678	
679	            const learnMoreBtn = document.getElementById('learn-more-btn');
680	            if (learnMoreBtn) {
681	                learnMoreBtn.addEventListener('click', function() {
682	                    const getStartedSection = document.getElementById('get-started');
683	                    if (getStartedSection) {
684	                        getStartedSection.scrollIntoView({ behavior: 'smooth', block: 'start' });
685	                        document.getElementById('name').focus();
686	                    }
687	                });
688	            }
689	
690	            const contactForm = document.getElementById('contact-form');
691	            if (contactForm) {
692	                const showError = (field, message) => {
693	                    const error = field.parentElement.querySelector('.field-error');
694	                    if (error) {
695	                        error.classList.add('show');
696	                        error.textContent = message;
697	                    }
698	                    field.setAttribute('aria-invalid', 'true');
699	                };
700	
701	                const clearError = (field) => {
702	                    const error = field.parentElement.querySelector('.field-error');
703	                    if (error) {
704	                        error.classList.remove('show');
705	                    }
706	                    field.setAttribute('aria-invalid', 'false');
707	                };
708	
709	                const validateField = (field) => {
710	                    const value = field.value.trim();
711	
712	                    if (!value) {
713	                        showError(field, 'This field is required');
714	                        return false;
715	                    }
716	
717	                    if (!field.checkValidity()) {
718	                        let message = 'Invalid input';
719	                        if (field.type === 'email') {
720	                            message = 'Please enter a valid email address';
721	                        } else if (field.id === 'name') {
